svg:`<svg viewBox="0 0 800 200" xmlns="http://www.w3.org/2000/svg" font-family="-apple-system,Segoe UI,Helvetica,Arial,sans-serif"><rect width="800" height="200" rx="14" fill="#243350"/><path d="M0 200 L0 150 Q220 118 440 152 L800 96 L800 200z" fill="#31456a" opacity=".55"/><g transform="translate(44,52) scale(1.5)"><circle cx="32" cy="32" r="33" fill="rgba(255,255,255,.10)" stroke="rgba(255,255,255,.35)" stroke-width="2.5"/><rect x="14" y="10" width="36" height="46" fill="#fff" stroke="#ffffff" stroke-width="3"/><g fill="#31456a"><rect x="20" y="16" width="9" height="7"/><rect x="35" y="16" width="9" height="7"/><rect x="20" y="28" width="9" height="7"/><rect x="35" y="28" width="9" height="7"/><rect x="20" y="40" width="9" height="7"/></g><rect x="35" y="40" width="9" height="16" fill="#8fa6c9"/></g><g transform="translate(198,52) scale(1.5)"><circle cx="32" cy="32" r="33" fill="rgba(255,255,255,.10)" stroke="rgba(255,255,255,.35)" stroke-width="2.5"/><path d="M10 24 l6 -12 h32 l6 12z" fill="#8fa6c9" stroke="#ffffff" stroke-width="3"/><rect x="12" y="24" width="40" height="28" fill="#fff" stroke="#ffffff" stroke-width="3"/><rect x="26" y="34" width="14" height="18" fill="#31456a"/></g><g transform="translate(352,52) scale(1.5)"><circle cx="32" cy="32" r="33" fill="rgba(255,255,255,.10)" stroke="rgba(255,255,255,.35)" stroke-width="2.5"/><path d="M18 26 l14 -14 14 14z" fill="#8fa6c9" stroke="#ffffff" stroke-width="3"/><path d="M32 26 v18" stroke="#ffffff" stroke-width="3.5"/><circle cx="32" cy="48" r="7" fill="#ffd98a" stroke="#ffffff" stroke-width="2.5"/></g><g transform="translate(506,52) scale(1.5)"><circle cx="32" cy="32" r="33" fill="rgba(255,255,255,.10)" stroke="rgba(255,255,255,.35)" stroke-width="2.5"/><path d="M14 32 L32 16 L50 32" fill="none" stroke="#ffffff" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M19 30 v18 h26 v-18" fill="none" stroke="#ffffff" stroke-width="3"/><rect x="28" y="36" width="8" height="12" fill="#8fa6c9"/></g><g transform="translate(660,52) scale(1.5)"><circle cx="32" cy="32" r="33" fill="rgba(255,255,255,.10)" stroke="rgba(255,255,255,.35)" stroke-width="2.5"/><circle cx="21" cy="32" r="9" fill="none" stroke="#ffffff" stroke-width="3.5"/><line x1="30" y1="32" x2="52" y2="32" stroke="#ffffff" stroke-width="3.5" stroke-linecap="round"/><line x1="44" y1="32" x2="44" y2="40" stroke="#8fa6c9" stroke-width="3.5" stroke-linecap="round"/><line x1="51" y1="32" x2="51" y2="40" stroke="#8fa6c9" stroke-width="3.5" stroke-linecap="round"/></g></svg>`
